package com.chetan.connectsuite.sync.v2

import java.io.File
import java.io.InputStream
import java.nio.file.Files
import java.nio.file.LinkOption

/**
 * **Stage 2 — several files from one `SEND_MULTIPLE`, prepared one at a time. Development only.**
 * docs/feature-a-multi-offer-proposal.md rev 4 §11–§15; docs/protocol.md → Share → Version 3 rule 5.
 * Pure JVM: everything Android (the shared URIs, the session, the offer, the readings) is behind [Env],
 * so a test reaches every rule with generated bytes.
 *
 * Replaces [ShareBatch]'s rev-3 whole-selection cap refusal (withdrawn by R7), which stays unwired.
 *
 * ### The rules, each in one place
 *
 * - **One copy at a time.** [evaluate] runs copies in sequence on its caller's thread; the caller runs it
 *   from one consumer, so two copies never overlap.
 * - **Each file is offered as soon as its copy is ready**, through [Env.offer]. From [Prep.Offered] on,
 *   the file's end belongs to `ShareFeature`, never to this queue.
 * - **Waiting for room (§12)**, for (a) the §4 budget refusing an extra copy (including a missing or
 *   stale reading), (b) 10 live offers, (c) an unknown-size retry that needs `Σ = 0`. Waiting files are
 *   retried oldest first, in selection order; a waiting file is never overtaken by another waiting file;
 *   only a never-tried file may go ahead of one.
 * - **It fails at once instead of waiting** when even with every held copy released the single-file
 *   rule refuses it: `s + M(s) > free + Σ`.
 * - **Unknown sizes (§14):** alone, bounded by the single-file limit and never retried. Beside held
 *   copies, attempt 1 is bounded by the budget; if it reaches the bound or a re-check stops it, its
 *   partial is deleted **and its absence verified**, then it waits for the one retry, which runs only at
 *   `Σ = 0`. A known size whose concurrent copy is stopped the same way takes the same path.
 * - **Selection-wide ends** ([end]): the screen closing, the session ending — including a reconnect,
 *   which is a different session ([Env.session]) and ends it the same way. They end every file not yet
 *   offered, cancel a running copy (whose partial [ShareStaging.copy] deletes), and never touch an
 *   offered file.
 * - **No shared URI open is admitted once [end] has taken effect** (§11), and **[end] never waits for a
 *   provider.** An open is admitted under [lock] while [ended] is null, and [end] sets [ended] under the
 *   same lock, so every open this queue ever calls was admitted before the end. An open admitted before
 *   the end and still inside the provider when it lands is left to finish on the queue's thread; its stream
 *   is then **closed with no byte read**, nothing is copied or offered from it, and it is not reported as a
 *   failure. (Until 2026-09-28 [end] waited for such an open to return — on the main thread, for as long
 *   as the provider took: finding F1, `docs/feature-a-v3-production-enablement.md` §6.) So when [end]
 *   returns, no open can be admitted; one admitted earlier may still be running, and reads nothing.
 * - **The §12 stall clock** ([StallClock]), PROPOSED and development only: a waiting file whose wait
 *   nothing in progress explains for [StallClock.RUN_LIMIT_MS], or that has waited [StallClock.CEILING_MS]
 *   in all, ends as [NotSentWhy.WaitedTooLong] — that file only, with nothing staged and nothing offered.
 * - **Nothing here says Sent or Saved.** Those belong to the offer (`ShareOffer.State`); this queue's
 *   last word on a file is [Prep.Offered].
 *
 * ### Not built, because the decisions are open (proposal §20)
 *
 * **Stop preparing** and the §13.3 notification.
 */
class ShareManyQueue(
    private val dir: File,
    /** The provider's claimed size of each item, in selection order (`null` when it gave none). */
    private val expected: List<Long?>,
    private val env: Env,
) {
    init {
        require(expected.size in 1..ShareSelection.MAX_FILES) { "a selection holds 1…${ShareSelection.MAX_FILES} files" }
    }

    /** Everything outside the queue. Each read is fresh; nothing is cached between evaluations. */
    interface Env {
        /** The `share.file` negotiated on the live session (0 with none) and `Σ` — `ShareFeature.stagingContext`. */
        fun context(): Pair<Int, Long>
        /**
         * The live session's identity, compared by reference only (`ShareFeature.liveSession`). The queue
         * pins the one it starts on; null means no identity is supplied, and nothing is pinned.
         */
        fun session(): Any? = null
        /** Live offers on the session — `ShareFeature.liveOfferIds().size`. */
        fun liveOffers(): Int
        /**
         * The live offers **in progress** — accepted: queued, receiving, or checking — and the bytes of
         * their copies (`ShareFeature.inProgress`). Only the §12 stall clock reads it.
         */
        fun inProgress(): Pair<Int, Long>
        /** Usable bytes on the staging volume, read now. */
        fun free(): Long
        /** The §4 budget's readings, or null when none can be supplied (then an extra copy waits). */
        fun concurrent(): ShareAdmission.Concurrent?
        /**
         * Opens item [index] (0-based). Called only while the screen that holds the grant is alive, and
         * never once [end] has taken effect.
         */
        fun open(index: Int): InputStream
        /** Offers a staged copy. On anything but `Offered` the copy is still this queue's, and it deletes it. */
        fun offer(index: Int, attemptId: String, bytes: Long, sha256: String): ShareFeature.OfferOutcome
        fun nowMs(): Long
        /** A monotonic clock (`SystemClock.elapsedRealtime`): the stall clock's only time source. */
        fun monotonicMs(): Long
        /** A copy of [attemptId] started (true) or ended (false) — so the app's sweeps skip it while it runs. */
        fun attempt(attemptId: String, running: Boolean) {}
        fun progress(index: Int, copied: Long) {}
        /**
         * Item [index] ended as not sent, for [why], before anything was staged to offer. [attemptId]
         * names the copy attempt, so a [NotSentWhy.CleanupUnverified] partial left in staging can be found
         * by its exact name — the queue never deletes it and never looks for it by listing. It is null
         * when no copy was attempted ([NotSentWhy.OpenFailed], [NotSentWhy.WaitedTooLong]). [cause] is an
         * exception's **class name** only — never its message, which for a provider refusal carries the URI.
         */
        fun notPrepared(index: Int, attemptId: String?, why: NotSentWhy, cause: String? = null) {}
    }

    sealed interface Prep {
        data object NotStarted : Prep
        data class Preparing(val copied: Long) : Prep
        /**
         * [paused]: the §12 stall clock is paused — the file waits only on offers already accepted.
         * Set by [states] from the clock; inside the queue it is always false.
         */
        data class Waiting(val reason: WaitReason, val paused: Boolean = false) : Prep
        /** Handed to `ShareFeature`: its row follows the offer from here. */
        data class Offered(val offerId: String, val bytes: Long) : Prep
        data class NotSent(val why: NotSentWhy) : Prep
    }

    sealed interface WaitReason {
        /** (a) The budget refused an extra copy. [limit] is the measured room, null when unmeasured. */
        data class NoRoom(val why: ShareConcurrentBudget.Refusal?, val limit: Long?) : WaitReason
        /** (b) The session already holds 10 live offers. */
        data object LiveLimit : WaitReason
        /** (c) Attempt 1 was stopped at its budget; the one retry waits for `Σ = 0`. */
        data object RetryAlone : WaitReason
    }

    sealed interface NotSentWhy {
        data object OpenFailed : NotSentWhy
        data object ReadFailed : NotSentWhy
        data class NoSpace(val needed: Long, val free: Long) : NotSentWhy
        /** Past the single-file limit (an unknown size, or a size the provider under-reported). */
        data class TooLarge(val limit: Long) : NotSentWhy
        data object WriteFailed : NotSentWhy
        data object CleanupUnverified : NotSentWhy
        data object OutOfRule : NotSentWhy
        /** The session at offer time did not negotiate an ordinary Send. */
        data object MacCannotReceive : NotSentWhy
        data object ScreenClosed : NotSentWhy
        data object Disconnected : NotSentWhy
        /** §12: the stall clock reached its running limit, or ([byCeiling]) the overall ceiling. */
        data class WaitedTooLong(val byCeiling: Boolean) : NotSentWhy
    }

    /**
     * **§12's stall clock, for one file.** PROPOSED, development only; the two limits are PROVISIONAL.
     * Pure: the caller supplies every instant, from a monotonic clock.
     *
     * - It **starts running** when the file first enters waiting, and the ceiling counts from that moment.
     * - Each evaluation sets it running or paused **until the next one** ([set]); [advance] credits the
     *   time since the last instant to the running total only if it was running.
     * - It is **never reset** while the file waits. If the file leaves waiting for its own copy attempt
     *   ([leave]) and comes back for the §14 retry ([resume]), the running total carries on; the copy's own
     *   time is not counted as running (the file was not waiting) but does count towards the ceiling.
     */
    class StallClock(val enteredMs: Long) {
        var runningMs = 0L
            private set
        private var lastMs = enteredMs
        /** true: running; false: paused; null: not waiting (its own copy runs) — nothing is credited. */
        private var counting: Boolean? = true
        val paused get() = counting == false

        fun advance(nowMs: Long) {
            if (counting == true) runningMs += (nowMs - lastMs).coerceAtLeast(0)
            lastMs = maxOf(lastMs, nowMs)
        }
        fun set(paused: Boolean) { if (counting != null) counting = !paused }
        fun leave(nowMs: Long) { advance(nowMs); counting = null }
        fun resume(nowMs: Long) { lastMs = maxOf(lastMs, nowMs); counting = true }

        /** Null while the file may keep waiting; otherwise how it ends. Call after [advance]. */
        fun expiry(nowMs: Long): NotSentWhy.WaitedTooLong? = when {
            runningMs >= RUN_LIMIT_MS -> NotSentWhy.WaitedTooLong(byCeiling = false)
            nowMs - enteredMs >= CEILING_MS -> NotSentWhy.WaitedTooLong(byCeiling = true)
            else -> null
        }

        companion object {
            /** PROVISIONAL, development only (§12, §20.6): 10 minutes of running time. */
            const val RUN_LIMIT_MS = 10 * 60_000L
            /** PROVISIONAL, development only (§12, §20.6): 60 minutes from entering waiting, paused or not. */
            const val CEILING_MS = 60 * 60_000L
        }
    }

    private class File1 {
        var prep: Prep = Prep.NotStarted
        /** §14: attempt 1 was stopped at its bound; the next try is the retry, alone, and the last. */
        var retryPending = false
        /** Created when the file first waits; kept (never reset) until the file ends or is offered. */
        var clock: StallClock? = null
    }

    private val files = List(expected.size) { File1() }
    private val lock = Any()
    /** Set once by [end]: from then on nothing is opened, copied or offered. */
    @Volatile private var ended: NotSentWhy? = null
    /** Copies this queue still owns (running or staged, not handed over). */
    private val owned = LinkedHashSet<String>()
    /**
     * The session this selection started on (§8: the session ending ends every file not yet offered). A
     * reconnect between two evaluations is a **different** session — possibly to a different Mac than the
     * one the review screen named — so it ends the selection as [NotSentWhy.Disconnected] rather than
     * offering the rest there. Set at the first evaluation that finds a session.
     */
    private var pinned: Any? = null
    private var pinnedYet = false

    /** Under [lock]: true when the live session is not the one this selection started on. */
    private fun sessionChangedLocked(): Boolean {
        val now = env.session()
        if (!pinnedYet) {
            pinned = now
            pinnedYet = true
            return false
        }
        return pinned != null && now !== pinned
    }

    /** Per-file reports made under [lock], delivered to [Env.notPrepared] outside it. */
    private val reports = ArrayList<Triple<Int, NotSentWhy, String?>>()

    fun states(): List<Prep> = synchronized(lock) {
        files.map { f -> (f.prep as? Prep.Waiting)?.copy(paused = f.clock?.paused == true) ?: f.prep }
    }

    /** True while any file is neither offered nor ended — the selection counts as a live attempt. */
    fun unfinished(): Boolean = synchronized(lock) { files.any { it.prep !is Prep.Offered && it.prep !is Prep.NotSent } }

    fun anyWaiting(): Boolean = synchronized(lock) { files.any { it.prep is Prep.Waiting } }

    /**
     * One evaluation (§12's retry triggers each call this): copy and offer every file that may go now,
     * one at a time, until none can. Returns how many copies it ran. Never throws for one file's failure.
     */
    fun evaluate(): Int {
        var ran = 0
        try {
            while (true) {
                val pick = synchronized(lock) { if (ended != null) null else choose() } ?: return ran
                deliverReports()
                run(pick)
                ran++
                // A Busy answer means the count read before the copy was stale. Stop here rather than copy the
                // same file again at once; the next trigger (an offer ending, or the 5 s tick) looks again.
                if (synchronized(lock) { (files[pick.index].prep as? Prep.Waiting)?.reason == WaitReason.LiveLimit }) return ran
            }
        } finally {
            deliverReports()
        }
    }

    /**
     * The screen closed, or the session ended: every file not yet offered is not sent, for [why]. Takes
     * only [lock], never a provider: it does not wait for an open, a read or a copy (see the class notes).
     */
    fun end(why: NotSentWhy): Int = synchronized(lock) {
        if (ended == null) ended = why
        for (f in files) if (f.prep !is Prep.Offered && f.prep !is Prep.NotSent) f.prep = Prep.NotSent(ended!!)
        // A copy still being written is left to run(), which sees [ended] and deletes it on return; an open
        // still inside the provider is left to run() too, which closes its stream unread.
        var removed = 0
        for (id in owned.toList()) {
            if (running == id) continue
            removed += ShareStaging.discard(dir, id)
            owned -= id
        }
        removed
    }

    private data class Pick(
        val index: Int,
        val limit: Long,
        /** Non-null only for an extra copy (`Σ > 0` at admission): re-checked while it runs. */
        val budget: ShareAdmission.Concurrent?,
        val retry: Boolean,
    )

    @Volatile private var running: String? = null

    private sealed interface Admit {
        data class Go(val pick: Pick) : Admit
        /** The file's state changed (it now waits for the first time, or ended): look again. */
        data object Changed : Admit
        /** It was already waiting and still waits. */
        data object Stays : Admit
    }

    private class Readings(val version: Int, val held: Long, val live: Int, val free: Long, val concurrent: ShareAdmission.Concurrent?)

    /** Under [lock]. */
    private fun choose(): Pick? {
        while (true) {
            val (version, held) = env.context()
            if (version == 0 || sessionChangedLocked()) {
                endLocked(NotSentWhy.Disconnected)
                return null
            }
            if (version < ShareOffer.QUEUE_VERSION && files.size > 1) {
                // A reconnect to a version-2 Mac mid-selection: it cannot take the rest.
                endLocked(NotSentWhy.MacCannotReceive)
                return null
            }
            val r = Readings(version, held, env.liveOffers(), env.free(), env.concurrent())
            tickLocked(r)
            val head = files.indexOfFirst { it.prep is Prep.Waiting }
            if (head >= 0) {
                when (val a = admit(head, r)) {
                    is Admit.Go -> return a.pick
                    Admit.Changed -> continue
                    Admit.Stays -> Unit
                }
            }
            val next = files.indexOfFirst { it.prep == Prep.NotStarted }
            if (next < 0) return null
            when (val a = admit(next, r)) {
                is Admit.Go -> return a.pick
                else -> continue
            }
        }
    }

    /**
     * Under [lock]: §12's stall clock, at one evaluation. For every waiting file, credit the time since the
     * last evaluation as it was then set; end the file if a limit is reached; then set it running or paused
     * until the next evaluation. A limit is checked **before** this evaluation's admission — the time was
     * already spent waiting.
     */
    private fun tickLocked(r: Readings) {
        val now = env.monotonicMs()
        var inProgress: Pair<Int, Long>? = null
        for ((i, f) in files.withIndex()) {
            if (f.prep !is Prep.Waiting) continue
            val clock = f.clock ?: StallClock(now).also { f.clock = it }
            clock.advance(now)
            clock.expiry(now)?.let { why ->
                f.prep = Prep.NotSent(why)
                f.clock = null
                reports += Triple(i, why, null)
                return@let
            }
            if (f.prep !is Prep.Waiting) continue
            clock.set(paused = pausedLocked(i, r, inProgress ?: env.inProgress().also { inProgress = it }))
        }
    }

    /**
     * Under [lock]: §12's pause rule (owner, 2026-09-28) — would the file be admitted **if every
     * in-progress offer's copy were released?** Admission is re-run on [hypothetical] numbers:
     * `Σ' = Σ − b`, `free' = free + b` and `live' = live − n`, where `n` and `b` are the in-progress offers
     * and their staged bytes; at `Σ' = 0` the single-file rule decides with no quota reading.
     *
     * **Hypothetical only.** Nothing here admits, reserves or credits anything: [admit] and the copy read
     * the measured `Σ` and `free`, so a paused file is still copied only once the space is really free.
     * The §4 budget's own readings (quota, this app's cache, usable space), used when `Σ' > 0`, are live
     * measurements and are **not** adjusted — only `Σ'` and `free'` are credited. An inconsistent or
     * overflowing reading keeps the clock running.
     */
    private fun pausedLocked(i: Int, r: Readings, inProgress: Pair<Int, Long>): Boolean {
        val h = hypothetical(r.live, r.held, r.free, inProgress.first, inProgress.second) ?: return false
        if (h.live >= ShareOffer.MAX_LIVE_OFFERS_V3) return false
        if (files[i].retryPending) return h.held == 0L && ShareStaging.preflight(expected[i], h.free) is ShareStaging.Preflight.Go
        return ShareAdmission.forCopy(r.version, expected[i], h.held, h.free, ShareAdmission.APPROVED_CAP, r.concurrent) is ShareAdmission.Copy.Go
    }

    /** Under [lock]: [f] waits for [reason]. Starts its stall clock, or resumes it if it waited before. */
    private fun waitLocked(f: File1, reason: WaitReason) {
        if (f.prep !is Prep.Waiting) {
            val now = env.monotonicMs()
            f.clock = f.clock?.also { it.resume(now) } ?: StallClock(now)
        }
        f.prep = Prep.Waiting(reason)
    }

    private fun admit(i: Int, r: Readings): Admit {
        val f = files[i]
        val wasWaiting = f.prep is Prep.Waiting
        fun wait(reason: WaitReason): Admit {
            waitLocked(f, reason)
            return if (wasWaiting) Admit.Stays else Admit.Changed
        }
        fun fail(w: NotSentWhy): Admit {
            f.prep = Prep.NotSent(w)
            f.clock = null
            return Admit.Changed
        }
        fun go(p: Pick): Admit {
            f.clock?.leave(env.monotonicMs())
            return Admit.Go(p)
        }
        val (held, live, free) = Triple(r.held, r.live, r.free)
        if (live >= ShareOffer.MAX_LIVE_OFFERS_V3) return wait(WaitReason.LiveLimit)
        if (f.retryPending) {
            // §14 (3): the only retry, alone, under the single-file rule.
            if (held > 0) return wait(WaitReason.RetryAlone)
            return when (val p = ShareStaging.preflight(expected[i], free)) {
                is ShareStaging.Preflight.Go -> go(Pick(i, p.limit, budget = null, retry = true))
                is ShareStaging.Preflight.NoSpace -> fail(NotSentWhy.NoSpace(p.needed, p.available))
            }
        }
        val s = expected[i]
        // §12: nothing that could end would make room — even with every held copy released it is refused.
        if (s != null && s + ShareStaging.margin(s) > free + held) return fail(NotSentWhy.NoSpace(s + ShareStaging.margin(s), free))
        return when (val c = ShareAdmission.forCopy(r.version, s, held, free, ShareAdmission.APPROVED_CAP, r.concurrent)) {
            is ShareAdmission.Copy.Go -> go(Pick(i, c.limit, budget = if (held > 0) r.concurrent else null, retry = false))
            is ShareAdmission.Copy.NoSpace ->
                if (held == 0L) fail(NotSentWhy.NoSpace(c.needed, c.free)) else wait(WaitReason.NoRoom(null, null))
            // No readings supplied: an extra copy is refused (the Stage A path), so it waits for Σ = 0.
            is ShareAdmission.Copy.CapNotApproved, is ShareAdmission.Copy.OverCap -> wait(WaitReason.NoRoom(null, null))
            is ShareAdmission.Copy.OverBudget -> wait(WaitReason.NoRoom(c.why, c.limit))
        }
    }

    private fun run(pick: Pick) {
        val i = pick.index
        val input: InputStream
        try {
            // Admission: under [lock], only while [ended] is null. [end] sets [ended] under the same lock.
            synchronized(lock) { if (ended != null) return; files[i].prep = Prep.Preparing(0) }
            input = env.open(i)
        } catch (e: Exception) {
            val report = synchronized(lock) {
                if (ended != null) return
                files[i].prep = Prep.NotSent(NotSentWhy.OpenFailed)
                files[i].clock = null
                true
            }
            if (report) env.notPrepared(i, null, NotSentWhy.OpenFailed, e.javaClass.name)
            return
        }
        val id = ShareStaging.newAttemptId()
        // One step with [end]: either the end has landed — the open was admitted before it and returned
        // after it, so its stream is closed unread (§11) — or this copy is registered before any end can.
        val proceed = synchronized(lock) {
            if (ended != null) false else {
                owned += id
                running = id
                true
            }
        }
        if (!proceed) {
            runCatching { input.close() }
            return
        }
        env.attempt(id, running = true)
        val outcome = try {
            ShareStaging.copy(
                source = input, dir = dir, attemptId = id, limit = pick.limit,
                available = { env.free() }, cancelled = { ended != null }, nowMs = env.nowMs(),
                afterBuffer = { n ->
                    synchronized(lock) { if (ended == null) files[i].prep = Prep.Preparing(n) }
                    env.progress(i, n)
                },
                budgetStop = pick.budget?.let { c -> { w -> ShareAdmission.stopCopying(c, { env.context().second }, w) } } ?: { null },
            )
        } finally {
            synchronized(lock) { running = null }
            env.attempt(id, running = false)
        }
        val after = synchronized(lock) { settle(i, id, pick, outcome) }
        // Only a copy that did not stage: a staged copy's refusal is reported by [Env.offer] itself.
        if (after is Prep.NotSent && outcome !is ShareStaging.Outcome.Staged) env.notPrepared(i, id, after.why)
    }

    /** Under [lock]: what one copy attempt's [outcome] makes of item [i]. */
    private fun settle(i: Int, id: String, pick: Pick, outcome: ShareStaging.Outcome): Prep {
        val f = files[i]
        if (outcome !is ShareStaging.Outcome.Staged) owned -= id // ShareStaging.copy deleted its own partial
        ended?.let { why ->
            // The screen closed or the session ended while this file was copying: not offered, not kept.
            if (outcome is ShareStaging.Outcome.Staged) {
                ShareStaging.discard(dir, id)
                owned -= id
            }
            f.prep = Prep.NotSent(why)
            return f.prep
        }
        val next = when (outcome) {
            is ShareStaging.Outcome.Staged -> offerLocked(i, id, outcome)
            is ShareStaging.Outcome.Cancelled -> Prep.NotSent(NotSentWhy.ScreenClosed)
            is ShareStaging.Outcome.OverLimit, is ShareStaging.Outcome.BudgetStopped ->
                if (pick.budget != null && !pick.retry) {
                    // §14 (2)/(4): attempt 1 of an extra copy reached its bound. Retry only once its
                    // partial is verifiably gone.
                    if (leftBehind(dir, id)) Prep.NotSent(NotSentWhy.CleanupUnverified)
                    else {
                        f.retryPending = true
                        waitLocked(f, WaitReason.RetryAlone)
                        f.prep
                    }
                } else {
                    Prep.NotSent(NotSentWhy.TooLarge(if (outcome is ShareStaging.Outcome.OverLimit) outcome.limit else pick.limit))
                }
            is ShareStaging.Outcome.NoSpace -> {
                val s = expected[i] ?: outcome.bytesWritten
                Prep.NotSent(NotSentWhy.NoSpace(s + ShareStaging.margin(s), outcome.available))
            }
            is ShareStaging.Outcome.SourceReadFailed -> Prep.NotSent(NotSentWhy.ReadFailed)
            is ShareStaging.Outcome.WriteFailed -> Prep.NotSent(NotSentWhy.WriteFailed)
        }
        if (next !is Prep.Waiting) f.clock = null
        f.prep = next
        return f.prep
    }

    /** Under [lock]: the hand-off. Exactly one of offer and delete happens to a staged copy. */
    private fun offerLocked(i: Int, id: String, staged: ShareStaging.Outcome.Staged): Prep {
        if (sessionChangedLocked()) {
            // The session changed while this file was copying: not offered on the new one, and not kept.
            ShareStaging.discard(dir, id)
            owned -= id
            endLocked(NotSentWhy.Disconnected)
            return Prep.NotSent(NotSentWhy.Disconnected)
        }
        val o = runCatching { env.offer(i, id, staged.bytes, staged.sha256) }.getOrElse { ShareFeature.OfferOutcome.Invalid(it.javaClass.name) }
        if (o is ShareFeature.OfferOutcome.Offered) {
            owned -= id
            return Prep.Offered(o.offerId, staged.bytes)
        }
        ShareStaging.discard(dir, id)
        owned -= id
        return when (o) {
            // C4: the phone's own limit — back to waiting for room, under the same cap.
            is ShareFeature.OfferOutcome.Busy -> {
                waitLocked(files[i], WaitReason.LiveLimit)
                files[i].prep
            }
            ShareFeature.OfferOutcome.NoSession -> {
                endLocked(NotSentWhy.Disconnected)
                Prep.NotSent(NotSentWhy.Disconnected)
            }
            is ShareFeature.OfferOutcome.NotNegotiated -> {
                endLocked(NotSentWhy.MacCannotReceive)
                Prep.NotSent(NotSentWhy.MacCannotReceive)
            }
            else -> Prep.NotSent(NotSentWhy.OutOfRule)
        }
    }

    private fun endLocked(why: NotSentWhy) {
        if (ended == null) ended = why
        for (f in files) if (f.prep !is Prep.Offered && f.prep !is Prep.NotSent && f.prep !is Prep.Preparing) f.prep = Prep.NotSent(why)
    }

    private fun deliverReports() {
        val out = synchronized(lock) { reports.toList().also { reports.clear() } }
        for ((i, why, cause) in out) env.notPrepared(i, null, why, cause)
    }

    /** The numbers §12's pause rule asks about: `live'`, `Σ'` and `free'`. Never used to admit. */
    data class Hypothetical(val live: Int, val held: Long, val free: Long)

    companion object {
        /**
         * `live − n`, `Σ − b` and `free + b` for [n] in-progress offers holding [bytes] — or **null**
         * (the clock runs) when the reading cannot be true or the sum cannot be represented: nothing in
         * progress, a negative input, more in progress than live, more of their bytes than `Σ`, or
         * `free + b` past `Long.MAX_VALUE`.
         */
        fun hypothetical(live: Int, held: Long, free: Long, n: Int, bytes: Long): Hypothetical? {
            if (n <= 0 || live < 0 || held < 0 || free < 0 || bytes < 0) return null
            if (n > live || bytes > held) return null
            if (bytes > Long.MAX_VALUE - free) return null
            return Hypothetical(live - n, held - bytes, free + bytes)
        }

        /**
         * §14's verification: is anything of [attemptId] still in [dir]? Looked at with links not
         * followed, by the attempt's own three names only — never by listing. An unreadable state
         * counts as left behind.
         */
        fun leftBehind(dir: File, attemptId: String): Boolean = listOf("part", "bin", "json").any { ext ->
            runCatching { Files.exists(File(dir, "$attemptId.$ext").toPath(), LinkOption.NOFOLLOW_LINKS) }.getOrDefault(true)
        }

        /**
         * The per-file `link.log` line for an item not sent before it was offered. Built only from
         * numbers, the attempt id, the reason's **type** and an exception's **class name** — there is no
         * parameter through which a file name, a URI or a path could reach it.
         */
        fun notPreparedLine(index: Int, total: Int, attemptId: String?, why: NotSentWhy, cause: String?): String {
            val detail = when (why) {
                is NotSentWhy.WaitedTooLong -> if (why.byCeiling) " (the ${StallClock.CEILING_MS / 60_000}-minute ceiling)"
                    else " (${StallClock.RUN_LIMIT_MS / 60_000} minutes of stalled waiting)"
                NotSentWhy.CleanupUnverified -> " — its partial may still be in staging; not retried, not deleted here (the next-start sweep is the backstop)"
                else -> ""
            }
            return "selection item ${index + 1}/$total" + (attemptId?.let { " attempt=$it" } ?: " (no copy attempted)") +
                " not sent: ${why::class.simpleName}" + (cause?.let { " ($it)" } ?: "") + detail
        }
    }
}
